function extractHandle(urlOrHandle = '') {
  if (!urlOrHandle) return '';
  const s = String(urlOrHandle).trim();
  return s
    .replace(/^https?:\/\/(www\.)?instagram\.com\//i, '')
    .replace(/\/.*$/, '')
    .replace(/^@/, '');
}

const clientId = inJson.id;
const username = extractHandle(inJson.instagram_profile_url)

return [
  {
    json: {
      ...inJson,
      clientId,
      platform: 'instagram',
      instagram_username: username,
      sheetDocId: inJson.sheetDocId ?? inJson.sheetDocID, // backstop if old key shows up
    }
  }
];

