// Canonicalize Apify post dataset items to:
// { posts: [{url, text, timestamp, likes, comments, isVideo}], followers }
// and enforce owner = target handle.

const items = $input.all();

// --- helpers ---
const toNum = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};
const isShortcode = (s) => /^[A-Za-z0-9_-]{5,15}$/.test(String(s||'').trim());
const makeUrlFromShortcode = (sc, isVideo=false) => {
  const code = String(sc || '').trim();
  if (!isShortcode(code)) return '';
  // Use /reel/ for obvious videos; otherwise /p/
  return isVideo ? `https://www.instagram.com/reel/${code}/`
                 : `https://www.instagram.com/p/${code}/`;
};

// target handle from Normalize Inputs (stable source)
const target = String($item(0).$node["Normalize Inputs"]?.json?.instagram_username || '')
  .replace(/^@/,'')
  .trim()
  .toLowerCase();

const posts = [];
let followers = 0;

for (const it of items) {
  const j = it.json || {};

  // --- enforce owner belongs to target account ---
  const owner =
    (j.ownerUsername ?? j.authorUsername ?? j.ownerUserName ?? j.owner?.username ?? '')
      .toString()
      .trim()
      .toLowerCase();

  if (target && owner && owner !== target) {
    // Not our account's post; skip
    continue;
  }

  // --- resolve core fields ---
  const isVideo = Boolean(
    j.isVideo === true ||
    j.is_video === true ||
    j.__typename === 'GraphVideo' ||
    j.product_type === 'clips' ||
    j.videoUrl || j.video_url
  );

  let url =
    j.url ||
    j.postUrl ||
    (j.shortcode ? makeUrlFromShortcode(j.shortcode, isVideo) : '');

  // If still no usable URL, skip (prevents whitelisting junk)
  if (!url) continue;

  const text = (j.text ?? j.caption ?? j.description ?? '').toString().trim();

  const timestamp =
    j.time ?? j.timestamp ?? j.takenAt ?? j.taken_at ?? j.createdAt ?? j.date ?? '';

  const likes =
    toNum(j.likes) ||
    toNum(j.likesCount) ||
    toNum(j.likeCount) ||
    toNum(j.likes_count) ||
    toNum(j.edge_liked_by?.count);

  const comments =
    toNum(j.comments) ||
    toNum(j.commentsCount) ||
    toNum(j.commentCount) ||
    toNum(j.comments_count) ||
    toNum(j.edge_media_to_comment?.count);

  posts.push({ url, text, timestamp, likes, comments, isVideo });

  // followers (if present on these items)
  const f =
    toNum(j.followers) ||
    toNum(j.followerCount) ||
    toNum(j.edge_followed_by?.count);
  followers = Math.max(followers, f);
}

// carry run meta if present
const meta = ($item(0).$node?.["Run Meta1"]?.json) || {};

return [{
  json: {
    ...$json,
    ...meta,
    posts,
    followers: toNum(followers, 0)
  }
}];

// Accept either {message:{content:{...}}} or direct JSON at root.
// Use timestamp (ISO) from LLM, not formatted dates.
const payload = $json ?? {};
const out = payload?.message?.content ?? payload ?? {};

function asInt(n){ n = Number(n); return Number.isFinite(n) ? Math.trunc(n) : 0; }
function asType(t){ return t === 'video' ? 'video' : 'image'; }

const top5 = Array.isArray(out.top5) ? out.top5.slice(0,5) : [];
const safeTop5 = top5.map((p,i)=>({
  url: String(p.url || ''),
  type: asType(p.type),
  likes: asInt(p.likes),
  comments: asInt(p.comments),
  timestamp: String(p.timestamp || p.date || ''), // allow 'date' fallback
  rank: i+1
}));

const best15 = Array.isArray(out.best15) ? out.best15.slice(0,15) : [];
const safeBest15 = best15.map(b=>({
  type: asType(b.type),
  text: String((b.text || '').trim()),
  likes: asInt(b.likes)
}));

return [{
  json: {
    ...$json,
    llm: {
      top5: safeTop5,
      posts30: asInt(out.posts30),
      posts90: asInt(out.posts90),
      best15: safeBest15
    }
  }
}];

// Add posts30/posts90 to each Top5 item, prefer raw computed counts over LLM.
// Falls back to LLM counts only if raw timestamps are unusable.

const runMeta = $item(0).$node["Run Meta1"]?.json || {};

const meta = {
  clientId: $json.clientId || runMeta.clientId || "noClientId",
  platform: String($json.platform || runMeta.platform || 'instagram').toLowerCase(),
  runId: $json.runId || runMeta.runId || "noRunId",
  isTest: $json.isTest ?? runMeta.isTest ?? true,
  sheetDocId: $json.sheetDocId || runMeta.sheetDocId || "",
};

const arr = $json.llm?.top5 ?? [];
const now = Date.now();
const days = (ms) => ms / 86400000;

// Compute counts from raw posts
const posts = Array.isArray($json.posts) ? $json.posts : [];
let c30 = 0, c90 = 0, validSeen = 0;
for (const p of posts) {
  const t = new Date(p.timestamp);
  if (!isNaN(t)) {
    validSeen++;
    const ageDays = days(now - t.getTime());
    if (ageDays <= 30) c30++;
    if (ageDays <= 90) c90++;
  }
}

// LLM numbers (for fallback only)
const llm30Raw = Number($json.llm?.posts30);
const llm90Raw = Number($json.llm?.posts90);
const llm30 = Number.isFinite(llm30Raw) ? llm30Raw : 0;
const llm90 = Number.isFinite(llm90Raw) ? llm90Raw : 0;

// Choose counts: raw if we had valid timestamps; otherwise LLM
let posts30 = validSeen > 0 ? c30 : llm30;
let posts90 = validSeen > 0 ? c90 : llm90;

// Sanity guards
if (!Number.isFinite(posts30)) posts30 = 0;
if (!Number.isFinite(posts90)) posts90 = 0;
if (posts90 < posts30) posts90 = posts30;      // enforce 30 ≤ 90
posts30 = Math.max(0, Math.trunc(posts30));
posts90 = Math.max(0, Math.trunc(posts90));

const yyyymm = new Date().toISOString().slice(0,7).replace('-',''); // YYYYMM

return arr.map((p) => ({
  json: {
    ...meta,
    rank: p.rank,
    postUrl: p.url,
    type: p.type,
    likes: p.likes,
    comments: p.comments,
    dateRaw: p.timestamp,
    posts30,
    posts90,
    writeKey: `${meta.clientId}|${meta.platform}|top${p.rank}|${yyyymm}`,
  }
}));

// Convert various date strings to MM/DD/YYYY as best-effort.
// If invalid/missing, leave blank.
function toMDY(s){
  if(!s) return '';
  const d = new Date(String(s).replace(/\.[0-9]{3}Z$/, 'Z'));
  if (isNaN(d)) {
    // try already formatted MM/DD/YYYY
    const mdy = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/;
    return mdy.test(s) ? s : '';
  }
  const mm = String(d.getMonth()+1).padStart(2,'0');
  const dd = String(d.getDate()).padStart(2,'0');
  const yyyy = String(d.getFullYear());
  return `${mm}/${dd}/${yyyy}`;
}

const out = [];
for (const it of $input.all()) {
  out.push({
    json: {
      ...it.json,
      date: toMDY(it.json.dateRaw)
    }
  });
}
return out;

// Code node v2: always read from $input.item.json
const inJson = $input.item.json;

function fail(msg) {
  const runId = inJson.runId || 'n/a';
  const e = new Error(`[VALIDATION] ${msg} | runId=${runId}`);
  e.name = 'InputValidationError';
  throw e;
}

if (!inJson.clientId) fail('Missing clientId');
if (inJson.platform !== 'instagram') fail(`Platform must be "instagram", got "${inJson.platform || 'undefined'}"`);
if (!inJson.instagram_username) fail('Missing instagram_username (handle)');

return [{ json: inJson }];

// Build compact inputs for tone and business summary.
const meta = $item(0).$node["Run Meta1"]?.json || {};
const profile = $item(0).$node["Profile Dataset Items"]?.json || {};

// Followers: pull from Profile Dataset Items first, then local fallback
const followers = Number(
  profile.followersCount ||
  profile.followsCount ||
  profile.followers ||
  $json.followers ||
  0
);

function clip(s, n = 280) {
  s = String(s || "").replace(/\s+/g, " ").trim();
  return s.length > n ? s.slice(0, n - 1) + "…" : s;
}

const best15 = Array.isArray($json.llm?.best15)
  ? $json.llm.best15.slice(0, 15)
  : [];
const toneInput = best15
  .map((b, i) => `${i + 1}. [${b.type}] ♥${b.likes} — ${clip(b.text, 220)}`)
  .join("\n");
const commentsText = best15
  .slice(0, 6)
  .map((b, i) => `${i + 1}. ${clip(b.text, 180)} (♥${b.likes}, ${b.type})`)
  .join("\n");

const posts30 = Number($json.llm?.posts30 || 0);
const posts90 = Number($json.llm?.posts90 || 0);

// AFTER MERGE: webOverview is present directly on $json
const overview = ($json.webOverview?.overview || "").toString().trim();
const website = ($json.webOverview?.website || "").toString().trim();

const summaryContext = {
  clientId: meta.clientId || $json.clientId || "noClientId",
  platform: meta.platform || "instagram",
  followers,
  posts30,
  posts90,
  website,
  overview,
  top5: Array.isArray($json.llm?.top5) ? $json.llm.top5.slice(0, 5) : [],
};

return [
  {
    json: {
      ...$json,
      summaryInputs: { toneInput, commentsText, summaryContext },
    },
  },
];

