// Assemble Summary Row — adds URLs to "Best-Performing Posts" and keeps everything else the same

const all = $items();
const meta = ($item(0).$node?.["Run Meta1"]?.json) || {};

// --- Find Build Summary Inputs payload ---
function findBuildSummary() {
  for (const i of all) {
    const nodeName = i.context?.node?.name || '';
    if (nodeName === 'Build Summary Inputs' || i.json?.summaryInputs) {
      return i.json?.summaryInputs || {};
    }
  }
  try {
    const build = $item(0).$node?.['Build Summary Inputs']?.json?.summaryInputs;
    if (build) return build;
  } catch (_) {}
  return {};
}

const buildSummary = findBuildSummary();
const summaryContext = buildSummary.summaryContext || {};
let commentsText = buildSummary.commentsText || '';
if (Array.isArray(commentsText)) commentsText = commentsText.join('\n');
commentsText = String(commentsText || '').trim();

// --- Pull tone & business summary from the two LLM outputs ---
function getText(item, needle) {
  const t = item?.json?.message?.content || '';
  return t.includes(needle) ? t : null;
}
const toneItem = all.find(i => getText(i, '•')) || all[0];
const bizItem  = all.find(i => getText(i, 'Business Research Ideas Summary')) || all[1];

const tone = (toneItem?.json?.message?.content || '').trim();
let biz  = (bizItem?.json?.message?.content  || '').trim();

// --- Meta/context ---
const posts30   = Number(summaryContext.posts30 || 0);
const posts90   = Number(summaryContext.posts90 || 0);
const clientId  = summaryContext.clientId || meta.clientId || $json.clientId || 'noClientId';
const platform  = (summaryContext.platform || meta.platform || $json.platform || 'instagram').toLowerCase();
const runId     = meta.runId || $json.runId || '';
const isTest    = (meta.isTest ?? $json.isTest ?? true) ? true : false;
const sheetDocId = meta.sheetDocId || meta.sheetDocID || $json.sheetDocId || '';

// --- Optional overview from webOverview ---
const overviewItem = all.find(i => i.json?.webOverview?.overview);
const overview = String(overviewItem?.json?.webOverview?.overview || '').trim();

// --- Build URL lines from top5 ---
const top5 = Array.isArray(summaryContext.top5) ? summaryContext.top5.slice(0, 5) : [];
const bestLines = top5.map(p => {
  const type = (p.type || '').toString().trim();
  const cap = type ? type[0].toUpperCase() + type.slice(1) : 'Post';
  const likes = Number(p.likes || 0);
  const url = String(p.url || '').trim();
  return `  - ${cap} ♥${likes} — ${url}`;
});

// --- Replace the "Best-Performing Posts" block in the LLM text with our URL list ---
function injectBestPosts(text, lines) {
  if (!lines.length) return text;

  // 1) Ideal: replace exactly the Best-Performing section up to the next "Insight:"
  const re = /(Best-Performing Posts\s*\(from top5\):)([\s\S]*?)(\n\s*Insight:)/i;
  if (re.test(text)) {
    return text.replace(re, (_, a, __, c) => `${a}\n${lines.join('\n')}${c}`);
  }

  // 2) If the heading is missing, insert after "Themes:" line inside Section 2
  const reThemes = /(2\.\s*Top-Performing[\s\S]*?Themes:[^\n]*\n)/i;
  if (reThemes.test(text)) {
    return text.replace(reThemes, (m) => `${m}Best-Performing Posts (from top5):\n${lines.join('\n')}\n`);
  }

  // 3) Fallback: append at end of Section 2 (before Section 3)
  const reSec2 = /(2\.\s*Top-Performing[\s\S]*?)(\n3\.)/i;
  if (reSec2.test(text)) {
    return text.replace(reSec2, (_, body, sec3) => `${body}\nBest-Performing Posts (from top5):\n${lines.join('\n')}\n${sec3}`);
  }

  // 4) Last resort: just append to the end
  return `${text}\n\nBest-Performing Posts (from top5):\n${lines.join('\n')}`;
}

let businessSummaryLLM = [overview, biz].filter(Boolean).join('\n\n').trim();
businessSummaryLLM = injectBestPosts(businessSummaryLLM, bestLines);

// --- Compose final row ---
const yyyymm = new Date().toISOString().slice(0, 7).replace('-', '');
return [
  {
    json: {
      writeKey: `${clientId}|${platform}|summary|${yyyymm}`,
      clientId,
      platform,
      sheetDocId,
      runId,
      isTest,
      posts30,
      posts90,
      businessSummary: businessSummaryLLM,
      toneVoiceLanguage: tone,
      commentExamples: commentsText,
    },
  },
];

