// Robustly extract strict JSON even if wrapped with <think> or prose
function pickRaw(j) {
  const c = [
    j?.choices?.[0]?.message?.content,
    j?.message?.content,
    j?.output_text,
    j?.data?.[0]?.text,
    j?.data?.[0]?.message?.content,
    j?.answer,
    j?.content
  ].filter(Boolean);
  return c[0] ?? '{}';
}
function stripCodeFences(s){ return String(s).replace(/^```(json)?\s*/i,'').replace(/```$/i,'').trim(); }
function extractFirstJsonObject(s){
  s = String(s);
  let start = s.indexOf('{'); if (start === -1) return null;
  let depth = 0;
  for (let i = start; i < s.length; i++){
    const ch = s[i];
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) { try { return JSON.parse(s.slice(start, i+1)); } catch {} } }
  }
  return null;
}

const raw = stripCodeFences(pickRaw($json));
let obj = {}; try { obj = JSON.parse(raw); } catch { obj = extractFirstJsonObject(raw) || {}; }

const s = x => (x ?? '').toString().trim();

/** Normalize to a full IG profile URL; accept handle or URL; return "" if not IG */
function toIgUrl(v){
  let val = s(v);
  if (!val) return '';
  // If it's already a URL, try to extract the first path segment (handle)
  const mUrl = val.match(/^(?:https?:\/\/)?(?:www\.)?instagram\.com\/([A-Za-z0-9._]+)/i);
  if (mUrl && mUrl[1]) {
    const handle = mUrl[1].replace(/^@/,'').toLowerCase();
    return `https://www.instagram.com/${handle}/`;
  }
  // Otherwise treat as handle
  const handle = val.replace(/^@/,'').match(/^[A-Za-z0-9._]+$/) ? val.replace(/^@/,'').toLowerCase() : '';
  return handle ? `https://www.instagram.com/${handle}/` : '';
}

const comps = Array.isArray(obj.competitors) ? obj.competitors : [];
const safeComps = comps
  .map(c => {
    const name = s(c?.name);
    const website = s(c?.website);
    const igUrl = toIgUrl(c?.instagram_url || c?.instagram || c?.instagram_username);
    return { name, website, instagram_url: igUrl };
  })
  .filter(c => c.instagram_url)               // must have a valid IG URL
  .slice(0, 8);

return [{
  json: {
    ...$json,
    webOverview: {
      overview: s(obj.overview),
      website: s(obj.website),
      competitors: safeComps
    }
  }
}];

