// For Each Competitor — bulletproof extraction & fan-out

// ---------- helpers ----------
function s(x){ return (x ?? '').toString().trim(); }

function normIgUrl(v){
  let val = s(v);
  if (!val) return '';
  // Already a URL?
  const mUrl = val.match(/^(?:https?:\/\/)?(?:www\.)?instagram\.com\/([A-Za-z0-9._]+)/i);
  if (mUrl && mUrl[1]) return `https://www.instagram.com/${mUrl[1].replace(/^@/,'').toLowerCase()}/`;
  // Otherwise treat as handle
  const handle = val.replace(/^@/,'');
  if (/^[A-Za-z0-9._]+$/.test(handle)) return `https://www.instagram.com/${handle.toLowerCase()}/`;
  return '';
}
function handleFromUrl(url){
  const m = (url || '').toString().trim().match(/^(?:https?:\/\/)?(?:www\.)?instagram\.com\/([A-Za-z0-9._]+)/i);
  return m && m[1] ? m[1].replace(/^@/,'').toLowerCase() : '';
}
function slug(x){
  return (s(x).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')) || 'unknown';
}

// Parse content out of a Perplexity item (robust to different shapes / <think> preambles)
function parsePerplexityToWebOverview(perpItemJson){
  function pickRaw(j) {
    const c = [
      j?.choices?.[0]?.message?.content,
      j?.message?.content,
      j?.output_text,
      j?.data?.[0]?.text,
      j?.data?.[0]?.message?.content,
      j?.answer,
      j?.content
    ].filter(Boolean);
    return c[0] ?? '{}';
  }
  function stripCodeFences(str){ return String(str).replace(/^```(json)?\s*/i,'').replace(/```$/i,'').trim(); }
  function extractFirstJsonObject(str){
    str = String(str);
    const start = str.indexOf('{');
    if (start === -1) return null;
    let depth = 0;
    for (let i = start; i < str.length; i++){
      const ch = str[i];
      if (ch === '{') depth++;
      else if (ch === '}'){
        depth--;
        if (depth === 0){
          try { return JSON.parse(str.slice(start, i+1)); } catch {}
        }
      }
    }
    return null;
  }

  try {
    const raw = stripCodeFences(pickRaw(perpItemJson));
    let obj = {};
    try { obj = JSON.parse(raw); } catch { obj = extractFirstJsonObject(raw) || {}; }
    const comps = Array.isArray(obj.competitors) ? obj.competitors : [];
    const safe = comps
      .map(c => ({
        name: s(c?.name),
        website: s(c?.website),
        instagram_url: normIgUrl(c?.instagram_url || c?.instagram || c?.instagram_username)
      }))
      .filter(c => !!c.instagram_url);
    return {
      overview: s(obj.overview),
      website: s(obj.website),
      competitors: safe
    };
  } catch {
    return { overview: '', website: '', competitors: [] };
  }
}

// ---------- harvest sources in priority order ----------
let web = $json?.webOverview;

// 1) current item fast-path
if (!web || !Array.isArray(web.competitors) || web.competitors.length === 0) {
  // 2) from Coerce Overview JSON
  const coerceItem = ($items('Coerce Overview JSON') || [])[0];
  const coerceWeb = coerceItem?.json?.webOverview;
  if (coerceWeb && Array.isArray(coerceWeb.competitors) && coerceWeb.competitors.length) {
    web = coerceWeb;
  }
}

// 3) if still empty, re-parse the raw Perplexity node (most reliable fallback)
if (!web || !Array.isArray(web.competitors) || web.competitors.length === 0) {
  const perpItem = ($items('Company Web Overview (Perplexity)') || [])[0];
  if (perpItem?.json) {
    web = parsePerplexityToWebOverview(perpItem.json);
  }
}

// ---------- finalize competitor list ----------
const comps = Array.isArray(web?.competitors) ? web.competitors : [];

// run meta
const meta = $item(0).$node?.['Run Meta1']?.json || $item(0).$node?.['Run Meta']?.json || {};
const clientId    = (meta.clientId || $json.clientId || 'noClientId').toString().trim() || 'noClientId';
const parentRunId = (meta.runId || $json.runId || '').toString().trim();
const sheetDocId  = (meta.sheetDocId || $json.sheetDocId || '').toString().trim();
const isTest      = (meta.isTest ?? $json.isTest) ?? false;
const yyyymm      = new Date().toISOString().slice(0,7).replace('-', '');

// normalize → dedupe → cap
const seen = new Set();
const normalized = [];
for (const c of comps) {
  const name = s(c.name);
  const website = s(c.website);
  const igUrl = normIgUrl(c.instagram_url || c.instagram || c.instagram_username);
  if (!igUrl) continue;
  const handle = handleFromUrl(igUrl);
  const key = (handle || name || website).toLowerCase();
  if (!key || seen.has(key)) continue;
  seen.add(key);
  normalized.push({ name, website, instagram_url: igUrl, handle });
  if (normalized.length >= 8) break;
}

// emit items or placeholder with debug
if (normalized.length === 0) {
  return [{
    json: {
      clientId,
      parentRunId,
      competitorRank: 0,
      competitorName: '',
      instagram_url: '',
      instagram_username: '',
      website: '',
      platform: 'instagram',
      writeKey: `${clientId}|competitor|none|${yyyymm}`,
      sheetDocId,
      isTest,
      _emptyFanout: true,
      _debug: {
        why: 'no_competitors_after_all_sources',
        hadCurrentWebOverview: !!$json?.webOverview,
        hadCoerceWebOverview: !!(($items('Coerce Overview JSON')||[])[0]?.json?.webOverview),
        hadPerplexityItem: !!(($items('Company Web Overview (Perplexity)')||[])[0]),
      }
    }
  }];
}

return normalized.map((c, i) => ({
  json: {
    clientId,
    parentRunId,
    competitorRank: i + 1,
    competitorName: c.name,
    instagram_url: c.instagram_url,
    instagram_username: c.handle,
